WITH base AS (SELECT id, product_name, category, cost, stock_qty, launch_date, tags, supplier_id, LAST_DAY(launch_date) AS launch_date_month_end, COALESCE(brand, 'UNKNOWN') AS brand_filled FROM products WHERE launch_date > DATE '2023-05-24' AND brand IS NOT NULL), eligible AS (SELECT s.* FROM base s WHERE NOT EXISTS (SELECT 1 FROM order_items ch WHERE ch.product_id = s.id AND ch.product_id = 1)), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY category, supplier_id ORDER BY cost DESC NULLS LAST, id) AS latest_rank FROM eligible) t WHERE latest_rank = 1), kept AS (SELECT s.* FROM latest s WHERE EXISTS (SELECT 1 FROM inventory c WHERE c.product_id = s.id AND c.last_restock >= s.launch_date)), deduped AS (SELECT id, category, stock_qty, supplier_id, launch_date_month_end, brand_filled, latest_rank FROM kept QUALIFY ROW_NUMBER() OVER (PARTITION BY supplier_id, category ORDER BY launch_date DESC, id) = 1), stats AS (SELECT CASE WHEN stock_qty >= 320 THEN 'PREMIUM' ELSE 'STANDARD' END AS stock_qty_tier, COUNT(*) AS row_count, COUNT(CASE WHEN category = 'Home' THEN 1 END) AS home_count, COUNT(DISTINCT category) AS distinct_categories, PERCENTILE_APPROX(stock_qty, ARRAY(0.25, 0.5, 0.75)) AS stock_qty_quartiles, COUNT(*) FILTER (WHERE category = 'Home') AS home_rows, PERCENTILE_APPROX(stock_qty, 0.5) AS stock_qty_p50 FROM deduped GROUP BY ROLLUP (CASE WHEN stock_qty >= 320 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING COUNT(*) > 1) SELECT row_count, home_count, distinct_categories, home_rows, stock_qty_p50 FROM stats ORDER BY distinct_categories DESC NULLS LAST, row_count;
